update public.learning_paths
set
  title = 'Digital Imaging (Photoshop)',
  goal = 'Digital Imaging (Photoshop)',
  summary = 'Students learn Photoshop as a professional image-making environment for design, photography, illustration, and visual communication, and build technical literacy in pixels, resolution, compression, color modes, and output-ready files. The course covers non-destructive layers, precise selections and masks, tonal and color correction, ethical retouching, compositing, type and layout integration, experimental effects, RAW and cross-app production, concept-driven image strategy, rights and inclusive practice, and delivery for print, web, social, and portfolio. Critique and a finished image series synthesize those skills.',
  data = $dimgjson${"slug": "digital-imaging-photoshop", "title": "Digital Imaging (Photoshop)", "description": "Students learn Photoshop as a professional image-making environment for design, photography, illustration, and visual communication, and build technical literacy in pixels, resolution, compression, color modes, and output-ready files. The course covers non-destructive layers, precise selections and masks, tonal and color correction, ethical retouching, compositing, type and layout integration, experimental effects, RAW and cross-app production, concept-driven image strategy, rights and inclusive practice, and delivery for print, web, social, and portfolio. Critique and a finished image series synthesize those skills.", "topics": [{"id": "52398aa2-7725-40dc-91b3-876805c70da8", "type": "topic", "title": "Digital Imaging Foundations and Photoshop Workspace", "description": "Understand Photoshop as a professional image-making environment for design, photography, illustration, and visual communication.", "children": [{"id": "918d27fc-c890-45de-b959-f3b5cf6d07cd", "type": "subtopic", "title": "Photoshop as a design tool", "children": [{"id": "33ec8d5b-de26-4227-9b2b-9f4d96c7e6ce", "type": "concept", "title": "Raster image editing in graphic design, photography, illustration, advertising, publishing, and social media"}, {"id": "4f7ab55d-ba1e-45d0-90eb-ca8b37b4d7dd", "type": "concept", "title": "Relationship among Photoshop, Illustrator, InDesign, Lightroom, Bridge, and web platforms"}, {"id": "c9e630c5-aaa5-4045-8847-1762bf1f2842", "type": "concept", "title": "When Photoshop is the right tool and when a vector, layout, motion, or web tool is better"}], "description": "This subtopic frames Photoshop as a visual communication environment, not only a software checklist."}, {"id": "01c3a322-e87a-4a1f-9582-160e2c4d22f3", "type": "subtopic", "title": "Workspace fluency", "children": [{"id": "0e120467-8815-44fb-a13d-5f14c2a13e09", "type": "concept", "title": "Tools panel, options bar, contextual task bar, layers panel, properties panel, adjustments, channels, paths, and history"}, {"id": "fb90622c-3f40-49ee-8ed4-06d6d08ce9e4", "type": "concept", "title": "Workspace customization, keyboard shortcuts, tool presets, guides, rulers, grids, and snapping"}, {"id": "56449045-fa0b-4429-bda2-719b4b71b643", "type": "concept", "title": "Zoom, pan, rotate view, screen modes, multiple documents, and comparison views"}], "description": "Students learn where tools, panels, preferences, and shortcuts live so attention can shift from menus to visual decisions."}, {"id": "850d35ca-5456-4d21-9f80-b2e658b9dbe9", "type": "subtopic", "title": "Professional file habits", "children": [{"id": "ea278dae-6405-4aa4-acdf-4d8e506baa73", "type": "concept", "title": "Project folders, original assets, working files, exports, linked files, and final deliverables"}, {"id": "1a51ce08-c1bd-4355-a262-b9e11192ddfb", "type": "concept", "title": "Layer naming, groups, color labels, notes, version numbers, and saved milestones"}, {"id": "69bdbae3-1954-487e-baea-ee5efc2b96ce", "type": "concept", "title": "Common mistakes: editing originals, flattening too early, losing links, and exporting the wrong size"}], "description": "Strong Photoshop practice begins with organized files, named layers, versioning, and backups."}]}, {"id": "b580a268-6880-4428-853c-e9b80dacd4ca", "type": "topic", "title": "Raster Image Fundamentals, Resolution, Color Modes, and File Formats", "description": "Build technical literacy around pixels, resolution, compression, bit depth, color modes, and output-ready files.", "children": [{"id": "016a99a9-b258-45bf-948c-8ab036dd95f1", "type": "subtopic", "title": "Pixels and resolution", "children": [{"id": "b8e708ec-90ee-4e2b-90ca-7e907376c8d4", "type": "concept", "title": "Pixels, image dimensions, ppi, dpi, resampling, interpolation, aspect ratio, and crop ratios"}, {"id": "388bba6b-313f-4fea-b928-692df973dcda", "type": "concept", "title": "Screen resolution versus print resolution and why 72 ppi myths persist"}, {"id": "70e997cd-6ca6-49d9-9fca-4f24cb239ef5", "type": "concept", "title": "Sharpening, noise, softness, and the limits of upscaling"}], "description": "Resolution determines how an image holds detail across screens, print, cropping, and enlargement."}, {"id": "c2e3e88b-238e-46ee-a3e6-eaff77d57bb2", "type": "subtopic", "title": "Color modes and bit depth", "children": [{"id": "6f00c355-7f59-4fc2-8965-593cca8f9310", "type": "concept", "title": "RGB, CMYK, grayscale, Lab, indexed color, duotone, spot color, and Pantone workflows"}, {"id": "2a95e892-d8d0-4fc8-b484-1735f7d3a115", "type": "concept", "title": "8-bit, 16-bit, 32-bit, dynamic range, banding, and tonal precision"}, {"id": "8a189941-ac19-48ac-9b4b-aeb4245445e3", "type": "concept", "title": "Color gamut, profiles, soft proofing, and conversion risks"}], "description": "Color modes affect what colors are available, how edits behave, and where a file can be used."}, {"id": "9829e3d5-2101-4fdd-a339-928910e1f681", "type": "subtopic", "title": "File formats and compression", "children": [{"id": "d8736c39-f36e-4786-a356-805d11896215", "type": "concept", "title": "PSD, PSB, TIFF, JPEG, PNG, GIF, PDF, HEIC, WebP, RAW, DNG, and SVG-adjacent workflows"}, {"id": "2e3f023a-a7da-4e15-b9a6-9f9b4fba1e91", "type": "concept", "title": "Lossless versus lossy compression, transparency, layers, metadata, and archive value"}, {"id": "b9bd6e15-c07b-4d51-b1e3-4fc4fef163ab", "type": "concept", "title": "Working file, production file, delivery file, and thumbnail file distinctions"}], "description": "Students learn to choose file formats by purpose instead of habit."}]}, {"id": "da92dce6-06b9-49a8-8d6e-6359e10353be", "type": "topic", "title": "Non-Destructive Workflow, Layers, Smart Objects, and Organization", "description": "Develop disciplined file structures that keep images editable, reversible, and production-ready.", "children": [{"id": "294d3ebc-e9ad-43b0-851f-5ca8ddbcda0a", "type": "subtopic", "title": "Layer-based thinking", "children": [{"id": "af131786-aa1a-4b67-b668-c86f66267739", "type": "concept", "title": "Pixel layers, adjustment layers, fill layers, shape layers, type layers, groups, clipping masks, and layer comps"}, {"id": "fdeed7c9-c70d-40d0-8226-36a2089597a0", "type": "concept", "title": "Opacity, fill, lock options, layer order, layer visibility, and isolation mode"}, {"id": "035149d0-6db7-46f7-8467-af8ae2a3461a", "type": "concept", "title": "Naming, grouping, nesting, and keeping a file readable for another designer"}], "description": "Layers let students build images as flexible systems of decisions rather than irreversible marks."}, {"id": "8c996b2b-d331-44cc-9c89-47b16b98ac47", "type": "subtopic", "title": "Smart Objects and reversibility", "children": [{"id": "a8def8d6-f9e5-475c-8e62-6f27d4829787", "type": "concept", "title": "Embedded versus linked Smart Objects, Smart Filters, Camera Raw Filter, transform preservation, and mockup workflows"}, {"id": "630eb324-eb97-4275-ba21-3cd183f4db5e", "type": "concept", "title": "Replacing contents, updating linked assets, scaling without repeated quality loss, and linked brand assets"}, {"id": "0df1adfe-3a4c-497f-b1ce-3da9ca28d48a", "type": "concept", "title": "When Smart Objects add value and when they make files unnecessarily heavy"}], "description": "Smart Objects preserve editability and make complex production workflows safer."}, {"id": "3aa1fd49-724a-466a-9deb-38db45488f5d", "type": "subtopic", "title": "Adjustment strategy", "children": [{"id": "9f4c7561-77d3-4304-b103-d6c0b641af09", "type": "concept", "title": "Curves, levels, hue/saturation, color balance, black and white, gradient maps, selective color, and lookup tables"}, {"id": "03743b5f-fec7-4075-84c6-2d5f8711992e", "type": "concept", "title": "Clipping adjustments, masks on adjustments, blend modes on adjustments, and targeted corrections"}, {"id": "28fd526b-9d11-4970-badd-b9759b08fffb", "type": "concept", "title": "Layer comps, alternate looks, revision files, and documenting edit decisions"}], "description": "Non-destructive adjustment helps students test visual directions and revise based on critique."}]}, {"id": "cd021746-bf32-4ea3-9345-3d92f3994a27", "type": "topic", "title": "Selections, Masks, Channels, and Edge Refinement", "description": "Learn how precise isolation and masking make sophisticated correction, retouching, and compositing possible.", "children": [{"id": "768efe22-ad09-4ea6-8412-75c4d586b48d", "type": "subtopic", "title": "Selection tools and judgment", "children": [{"id": "1cf52302-6186-4d53-b340-c9b825826e1b", "type": "concept", "title": "Marquee, lasso, object selection, quick selection, magic wand, pen paths, color range, focus area, and select subject"}, {"id": "da7f5e55-976c-43cf-92b2-387c414737bc", "type": "concept", "title": "Hard edges, soft edges, hair, transparent objects, shadows, reflections, and motion blur"}, {"id": "702ad00f-6112-46e4-8a46-593bb74edba0", "type": "concept", "title": "Adding, subtracting, intersecting, feathering, smoothing, expanding, and contracting selections"}], "description": "Selections are the foundation for isolating image areas, but students must choose the tool that fits the edge."}, {"id": "bb1334d9-4444-4ca3-a9a8-b8f9ae2eed1e", "type": "subtopic", "title": "Layer masks and vector masks", "children": [{"id": "be802438-a997-4eaa-8896-7656d9e62da2", "type": "concept", "title": "White, black, and gray mask logic; brushwork on masks; mask density and feather"}, {"id": "60b78602-1418-412e-bb9d-616001f2f9cc", "type": "concept", "title": "Vector masks, paths, shape edges, and combining raster and vector masks"}, {"id": "b34d9f5b-ed81-48da-8452-3212d9a4438f", "type": "concept", "title": "Clipping masks, nested masks, adjustment masks, and mask troubleshooting"}], "description": "Masks teach students to hide and reveal information without deleting it."}, {"id": "9b1abe75-d69d-4bc5-acd9-323126abd1a5", "type": "subtopic", "title": "Channels and advanced edge work", "children": [{"id": "c618332b-7572-418e-84e9-7c9171394bf5", "type": "concept", "title": "Alpha channels, luminosity masks, channel calculations, contrast-based masks, and blend-if controls"}, {"id": "dc352659-c211-41c6-b37f-bd938cbf9b26", "type": "concept", "title": "Select and Mask workspace, refine edge brush, decontaminate colors, and hair/fur/fabric edges"}, {"id": "4edfef4e-29f3-4f62-898b-5f682bdb7089", "type": "concept", "title": "Checking masks against black, white, color, and transparent backgrounds"}], "description": "Channels give students a deeper route into complex selections and image structure."}]}, {"id": "387ba246-c92d-4b9b-9e3e-e5e5b372b8db", "type": "topic", "title": "Tonal Correction, Color Correction, and Color Management", "description": "Control contrast, exposure, color balance, and device-dependent color so images reproduce with intention.", "children": [{"id": "f10e385f-b69d-4608-ad4b-161ce90271cd", "type": "subtopic", "title": "Tonal structure", "children": [{"id": "a860ecb8-1c30-446a-b096-01267de0ef82", "type": "concept", "title": "Histogram reading, levels, curves, exposure, contrast, black point, white point, midtones, highlight recovery, and shadow detail"}, {"id": "91c6bcd3-d279-4a7a-84c6-e68b7cbd9743", "type": "concept", "title": "Local versus global correction, dodge and burn, luminosity control, and tonal separation"}, {"id": "3e6b2dc5-eaf9-489f-ae0d-27233cdcd0bf", "type": "concept", "title": "Avoiding crushed shadows, clipped highlights, muddy midtones, and overprocessed contrast"}], "description": "Tone correction establishes whether an image has usable detail, hierarchy, and visual depth."}, {"id": "b48a25c6-1ea8-4a95-b846-315971ae6eae", "type": "subtopic", "title": "Color correction", "children": [{"id": "0aef54c1-f452-4ac0-97ad-11fc28d4435d", "type": "concept", "title": "White balance, neutral correction, color casts, skin tone, product color, memory color, and palette matching"}, {"id": "21e2a0b3-1b65-4ab2-876b-7c0859ca3bbd", "type": "concept", "title": "Hue/saturation, vibrance, selective color, color balance, gradient maps, and camera profiles"}, {"id": "1ec7de60-2059-4818-875e-543c74b7b35b", "type": "concept", "title": "Color grading versus correction and matching multiple images in a series"}], "description": "Color correction teaches students to make images accurate, expressive, or system-consistent."}, {"id": "b47db294-5dd2-4c75-96b8-5692500f0cd3", "type": "subtopic", "title": "Color management", "children": [{"id": "7178497e-721b-4c58-9ee9-d6de79d9da27", "type": "concept", "title": "ICC profiles, working spaces, sRGB, Adobe RGB, Display P3, CMYK profiles, soft proofing, and rendering intents"}, {"id": "4914ab8f-e7bc-400b-86fa-c90ea7489e2b", "type": "concept", "title": "Monitor calibration, proof setup, gamut warning, rich black, total ink limit, and profile conversion"}, {"id": "cddc3c15-40a2-4003-924c-1488fd02d5df", "type": "concept", "title": "Communicating color requirements with printers, clients, developers, and collaborators"}], "description": "Color management connects screen decisions to print, web, and production reality."}]}, {"id": "eb35c721-ff19-4e88-a4df-6e1f6f1c576a", "type": "topic", "title": "Retouching, Restoration, and Image Cleanup", "description": "Use ethical, controlled retouching methods to repair, clarify, and enhance images without destroying credibility.", "children": [{"id": "5d3c1a74-ffaf-4960-a009-5f8a98fb10c4", "type": "subtopic", "title": "Core retouching tools", "children": [{"id": "dfc935b3-c109-488b-8731-c9821a5b03da", "type": "concept", "title": "Clone stamp, healing brush, spot healing, patch tool, content-aware fill, remove tool, and generative-style removal awareness"}, {"id": "ae7bbc00-cd31-4bda-8909-956c2bfba30f", "type": "concept", "title": "Sampling, alignment, texture preservation, frequency awareness, and working on blank retouching layers"}, {"id": "8097e3db-3ae8-491d-a4e7-c4dc82802182", "type": "concept", "title": "Dust, scratches, blemishes, distractions, seams, sensor spots, and background cleanup"}], "description": "Students learn cleanup tools as controlled interventions rather than automatic fixes."}, {"id": "8bc30475-7e9f-4c45-b537-4f313e00aef3", "type": "subtopic", "title": "Portrait and product retouching", "children": [{"id": "aacc08cf-5c79-47f2-b433-ce2bc2f10bff", "type": "concept", "title": "Skin texture, flyaways, wardrobe distractions, reflections, product surfaces, labels, symmetry, and edges"}, {"id": "bcc75274-6239-40b2-98b9-e0b611c9ccce", "type": "concept", "title": "Frequency separation basics, dodge and burn, liquify restraint, color cleanup, and realistic shadow work"}, {"id": "e7268af0-823d-46e6-b54d-e31948f01d7e", "type": "concept", "title": "Ethical boundaries for beauty, documentary, editorial, product, and archival contexts"}], "description": "Retouching should support communication goals while respecting texture, identity, and credibility."}, {"id": "d01777c6-1768-457a-b8bb-6407bc0d4d3a", "type": "subtopic", "title": "Restoration and repair", "children": [{"id": "9b477d3a-680d-43e3-8217-56fee94826b1", "type": "concept", "title": "Scanning, dust and scratch removal, tear repair, tonal restoration, color fading, stains, missing areas, and grain management"}, {"id": "7372733e-0f24-45da-a0b0-1328041cc78e", "type": "concept", "title": "Working from duplicate layers, preserving source files, and comparing before/after states"}, {"id": "9112d7ed-1f80-424b-ace7-3660af31c0a2", "type": "concept", "title": "Metadata, provenance, uncertainty, and when not to over-restore"}], "description": "Restoration teaches students to reconstruct damaged images while documenting assumptions."}]}, {"id": "31933ded-7df8-4d5b-81b2-c728897352a4", "type": "topic", "title": "Compositing, Photomontage, and Constructed Images", "description": "Combine images into persuasive, believable, or intentionally expressive composites with coherent light, scale, and perspective.", "children": [{"id": "b2e2b654-1524-4d11-8e8f-c1cc622dce4e", "type": "subtopic", "title": "Composite construction", "children": [{"id": "d4f6e7a1-7811-4a40-8d71-185f56b8234e", "type": "concept", "title": "Cutouts, masks, perspective, scale, horizon, depth cues, vanishing points, and spatial logic"}, {"id": "ea702d0e-2918-49dc-8756-8accc15875c6", "type": "concept", "title": "Light direction, shadow shape, contact shadows, reflected light, color temperature, grain, sharpness, and atmospheric perspective"}, {"id": "1f0c010f-210a-4f66-8501-f0699dbfdea0", "type": "concept", "title": "Believable realism, surreal collage, editorial montage, and conceptual image construction"}], "description": "Compositing asks students to make many pieces behave as one visual world or one purposeful collage."}, {"id": "3210024e-dcaf-4fd0-a5ee-9f41792c37d4", "type": "subtopic", "title": "Blend modes and transparency", "children": [{"id": "0f219898-d6c9-4d9a-9b39-09531316d847", "type": "concept", "title": "Multiply, screen, overlay, soft light, hard light, color, luminosity, difference, and normal blend behavior"}, {"id": "fc254c4b-915e-4dbb-8aa1-081965db7a24", "type": "concept", "title": "Texture overlays, double exposure, tonal blending, color blending, and blend-if sliders"}, {"id": "c40fabaf-cf06-4990-9ec7-42e0883b969b", "type": "concept", "title": "Opacity, fill, clipping, masks, and stacking order interactions"}], "description": "Blend modes are image mathematics that can become powerful visual language when used deliberately."}, {"id": "86756507-95a1-40f6-8967-42202b2a6067", "type": "subtopic", "title": "Photomontage and meaning", "children": [{"id": "28723522-d217-4622-b719-e7bb760956da", "type": "concept", "title": "Juxtaposition, metaphor, sequence, scale shift, archival fragments, found imagery, and visual rhetoric"}, {"id": "8528fbbf-04b2-4d00-9cbf-c34b694e5318", "type": "concept", "title": "Dada, surrealism, political montage, advertising, album art, posters, and contemporary digital collage"}, {"id": "41f76307-1df6-4ecb-869f-84653e32506e", "type": "concept", "title": "Credit, permissions, appropriation, transformation, and audience interpretation"}], "description": "Constructed images carry arguments, narratives, and cultural references."}]}, {"id": "450a0ede-187e-4210-a891-4f561a9605f5", "type": "topic", "title": "Type, Graphics, Layout, and Design Integration", "description": "Integrate raster images with typography, vector graphics, hierarchy, grids, and brand or editorial systems.", "children": [{"id": "2115ce65-c69e-4eee-a369-3cbed0d687ec", "type": "subtopic", "title": "Type in Photoshop", "children": [{"id": "beaee581-db39-485f-ae94-1ea33290c5bf", "type": "concept", "title": "Type layers, character and paragraph panels, alignment, tracking, leading, hierarchy, legibility, and rasterization risks"}, {"id": "7e9bdb61-8a70-49d5-b0d0-ae804e5ae340", "type": "concept", "title": "Type masks, clipping images into type, text effects, and title treatments"}, {"id": "473091cb-7874-485d-8e59-c246f06bc82a", "type": "concept", "title": "Handing off type-heavy work to Illustrator, InDesign, Figma, or layout tools when needed"}], "description": "Students learn when Photoshop type is appropriate and how to keep it readable, editable, and production-safe."}, {"id": "5d2b4f75-ee64-47df-a121-d93a67f7e831", "type": "subtopic", "title": "Graphic elements and hierarchy", "children": [{"id": "90868826-7d6f-413c-9ca8-dea653c245be", "type": "concept", "title": "Shapes, strokes, gradients, patterns, icons, grids, guides, margins, visual hierarchy, scale, and alignment"}, {"id": "20e84a03-6f44-48a1-86b9-a77b009169a3", "type": "concept", "title": "Poster, social tile, editorial opener, album cover, event graphic, and campaign mockup contexts"}, {"id": "484680d7-b1ab-4939-ade6-f45085340f77", "type": "concept", "title": "Balancing image, type, logo, caption, call to action, and negative space"}], "description": "Image edits become design when they are organized into a communicative hierarchy."}, {"id": "24c4f6e4-4fdf-449e-b595-02a56efe5c9c", "type": "subtopic", "title": "Design system integration", "children": [{"id": "f2841bea-36f8-4273-8d05-6fc1de222509", "type": "concept", "title": "Brand colors, type systems, asset libraries, style guides, templates, smart mockups, and artboards"}, {"id": "c8493256-7ca2-4747-9c00-50859475f245", "type": "concept", "title": "Consistency across print, web, social, presentation, and portfolio outputs"}, {"id": "315d20e5-5c9d-4f30-887a-6669eec7bddd", "type": "concept", "title": "Exporting layered assets for collaborators while preserving editability"}], "description": "Photoshop work often lives inside larger identity systems and multi-format campaigns."}]}, {"id": "2f0b71df-38c1-460b-bb9a-56eeb812c0b5", "type": "topic", "title": "Filters, Effects, Texture, and Experimental Image-Making", "description": "Use effects and image transformations as deliberate visual language rather than decoration.", "children": [{"id": "71f3296d-dcc1-45d5-a223-df6e9b360e8d", "type": "subtopic", "title": "Filters as process", "children": [{"id": "e168784c-f8f6-4bdd-a9f1-295ed89267f1", "type": "concept", "title": "Blur, sharpen, noise, distort, liquify, displacement, render, neural-style tools, and Camera Raw filter"}, {"id": "a862cccc-4672-40ae-9bc9-cd71ef203360", "type": "concept", "title": "Smart Filters, filter masks, stacking filters, and maintaining reversibility"}, {"id": "16e2b47e-1329-4677-a9cd-6fff6bef2711", "type": "concept", "title": "Avoiding default-looking effects, cliches, and accidental overprocessing"}], "description": "Filters become useful when students understand what they do and why an effect supports the image."}, {"id": "b2e786a1-b531-4556-ade6-767b24162421", "type": "subtopic", "title": "Texture and surface", "children": [{"id": "6ae06e44-0dba-4f3a-9a75-7f18b6324288", "type": "concept", "title": "Grain, paper, halftone, scan artifacts, paint texture, photocopy effects, scratches, and overlays"}, {"id": "24929e7f-36f7-492e-9ae4-da4b77ebeca7", "type": "concept", "title": "Displacement maps, blending texture into light and shadow, and matching texture across elements"}, {"id": "9dae53f1-d84f-4235-b40b-c3c7ea340b63", "type": "concept", "title": "Using texture for mood, authenticity, history, or critique"}], "description": "Texture gives digital images material presence and can connect work to print, photography, drawing, and collage."}, {"id": "458bff6c-08cc-4dd3-a7ce-a61c284711d3", "type": "subtopic", "title": "Experimental workflows", "children": [{"id": "c50e66e6-1f28-4f15-bdd8-5bf7e6ffb19c", "type": "concept", "title": "Glitch, scanography, data bending awareness, generative patterns, procedural textures, and collage systems"}, {"id": "fba8db19-0c52-4b65-add2-440d9ebdd205", "type": "concept", "title": "Iteration, chance operations, constraints, batch processing, and image series development"}, {"id": "e1c0155d-e83b-4bb7-ab5a-4c1048ca7b26", "type": "concept", "title": "Documenting process so experiments become design knowledge"}], "description": "Experimental imaging expands Photoshop beyond correction into studio practice."}]}, {"id": "1a2aebdd-6b22-4738-9e94-e1443cb4a1f5", "type": "topic", "title": "Photography Workflow, RAW Processing, and Cross-App Production", "description": "Connect Photoshop to camera files, Lightroom, Bridge, Illustrator, InDesign, and portfolio workflows.", "children": [{"id": "a01faf42-3497-4361-bb93-cb3a0d88c169", "type": "subtopic", "title": "RAW and camera workflow", "children": [{"id": "40dfb1a5-cd3c-4863-bef3-cf916459c262", "type": "concept", "title": "RAW files, DNG, Camera Raw, white balance, exposure, lens corrections, noise reduction, and sharpening"}, {"id": "d8be4f5f-5513-4ad4-8ff0-74b885f9586c", "type": "concept", "title": "Lightroom and Bridge workflows, selects, ratings, keywords, collections, and contact sheets"}, {"id": "a3307b56-7261-4685-9e32-b030f721ef02", "type": "concept", "title": "From capture to edit: naming, importing, backing up, and preserving originals"}], "description": "Students learn how source image quality affects every downstream Photoshop decision."}, {"id": "2ae1c67e-43c1-424c-a376-7c3d9833cacb", "type": "subtopic", "title": "Cross-app workflows", "children": [{"id": "4fb3ac03-428b-497e-be38-f685a6304e43", "type": "concept", "title": "Photoshop with Lightroom, Bridge, Illustrator, InDesign, Acrobat, Figma, After Effects, and web CMS tools"}, {"id": "b0cf3ed9-0e3d-4d6f-b244-30f4a05f95dd", "type": "concept", "title": "Linked assets, placed files, copy-paste risks, embedded color profiles, and export handoff"}, {"id": "df46bfd5-1284-4379-9f5f-3bedb49d09c2", "type": "concept", "title": "Packaging, shared folders, cloud documents, version conflicts, and collaborative review"}], "description": "Professional image work often moves among several tools and collaborators."}, {"id": "0bf81f12-1835-440b-8acf-09bc0301a4bd", "type": "subtopic", "title": "Image series consistency", "children": [{"id": "731747fc-91c7-40a2-b664-068c06e00bbe", "type": "concept", "title": "Batch edits, actions, presets, synchronized Camera Raw settings, contact sheets, and visual consistency"}, {"id": "efe6e085-2218-4fda-945f-0289b3187753", "type": "concept", "title": "Matching crop, tone, color, grain, shadows, product angles, backgrounds, and naming conventions"}, {"id": "5c1c0866-ec8e-40bd-b549-f8d6ed5881c1", "type": "concept", "title": "Series logic for portfolios, campaigns, social posts, editorial packages, and exhibitions"}], "description": "Designers often need sets of images to feel related, not just individual hero images."}]}, {"id": "d2dd215f-1cf0-4618-b51b-459cbee04a44", "type": "topic", "title": "Visual Research, Concept Development, and Image Strategy", "description": "Move beyond software exercises into concept-driven image systems that solve communication problems.", "children": [{"id": "b008f921-375c-4897-9f82-f4fd84a38c07", "type": "subtopic", "title": "Research and references", "children": [{"id": "064e7e58-2b40-4903-a039-02d3b84c4efa", "type": "concept", "title": "Mood boards, precedent studies, image banks, artist references, design history, photography references, and campaign analysis"}, {"id": "7a7c4893-7413-4feb-86b4-2b9f82dfed56", "type": "concept", "title": "Research ethics, source tracking, reference transformation, and avoiding plagiarism"}, {"id": "a0fb9019-e4e5-4fb1-954e-0693457dabfe", "type": "concept", "title": "Reading an image for audience, tone, genre, medium, and cultural context"}], "description": "Visual research helps students make informed choices rather than copying surface style."}, {"id": "aed659b7-7d2e-458d-8a54-77451979c0bf", "type": "subtopic", "title": "Concept development", "children": [{"id": "2ccf98a4-6640-4d17-9c5e-c0a7e29205a4", "type": "concept", "title": "Brief analysis, audience, message, constraints, deliverables, keywords, sketches, thumbnails, and concept boards"}, {"id": "d09bd5ec-324b-4c44-b499-56353aaff3e0", "type": "concept", "title": "Choosing image strategy: documentary, surreal, clean product, editorial, expressive, archival, or typographic"}, {"id": "5c2fa1a7-3307-4f5b-af20-bbab93eaf96c", "type": "concept", "title": "Testing multiple directions and selecting based on criteria rather than taste alone"}], "description": "Photoshop projects should start with a communication problem or artistic question."}, {"id": "095ef42f-1fcc-49d5-b203-e9b7ad8defc1", "type": "subtopic", "title": "Image systems", "children": [{"id": "6d400773-0a48-4e1c-95a2-8baabff7215a", "type": "concept", "title": "Series, sequence, variation, campaign family, visual rules, templates, and modular assets"}, {"id": "b2eea37c-3152-415a-b621-03397e83bd2d", "type": "concept", "title": "Consistency and surprise, rhythm and contrast, hierarchy and repetition"}, {"id": "e078d5c0-70bc-4aeb-9598-b7468f96ab14", "type": "concept", "title": "Connecting image strategy to typography, color, brand, platform, and context"}], "description": "World-class design programs ask students to build systems, not only one-off images."}]}, {"id": "0164bab3-ed7f-43eb-99bc-101c43f6e173", "type": "topic", "title": "Ethics, Copyright, Inclusive Imagery, and AI-Aware Practice", "description": "Build responsible habits around manipulation, authorship, consent, representation, accessibility, and emerging tools.", "children": [{"id": "ca1cb874-62d1-4768-916d-4af6191fc2b5", "type": "subtopic", "title": "Manipulation ethics", "children": [{"id": "618e7faf-d71d-4cf5-92e6-e763e756d909", "type": "concept", "title": "Editorial versus advertising standards, documentary truth claims, disclosure, body image, product accuracy, and archival integrity"}, {"id": "77fa3832-eeed-4d8a-b1c5-497d8f65a272", "type": "concept", "title": "Before/after transparency, retouching boundaries, and context-dependent expectations"}, {"id": "32393d4a-8bdf-4d7a-b9d2-bc6392dece13", "type": "concept", "title": "Consequences of misleading edits for trust, identity, culture, and public information"}], "description": "Image editing changes how viewers understand reality, people, products, events, and evidence."}, {"id": "0eb8d800-c2eb-4909-8e54-9d4c01860854", "type": "subtopic", "title": "Rights and authorship", "children": [{"id": "f379a65e-67d6-469a-949e-0f4e0690c786", "type": "concept", "title": "Copyright, fair use, licenses, Creative Commons, public domain, model releases, property releases, trademarks, and attribution"}, {"id": "9db42937-1413-4f58-ae17-c1c666be3797", "type": "concept", "title": "Stock imagery, archives, museum collections, dataset provenance, and client-provided assets"}, {"id": "5f13d3be-671a-4cd7-9e2f-1a26ca442cc9", "type": "concept", "title": "Maintaining source logs and documenting permissions"}], "description": "Students need practical copyright literacy before using found images, fonts, textures, and generated assets."}, {"id": "073034e1-6290-4c62-9322-d0e816c571f6", "type": "subtopic", "title":